mapper.select:
SELECT r.*, u.nickname, u.avatar, a.title AS activityTitle, a.cover_image AS activityCover, a.points AS activityPoints, a.volunteer_duration AS activityDuration FROM activity_registration r LEFT JOIN sys_user u ON r.user_id = u.id LEFT JOIN activity a ON r.activity_id = a.id
AND r.activity_id = #{query.activityId}
AND r.user_id = #{query.userId}
AND r.status = #{query.status}
AND u.nickname LIKE CONCAT('%', #{query.nickname}, '%')
AND a.title LIKE CONCAT('%', #{query.activityTitle}, '%')
ORDER BY r.create_time DESC

